return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Swedish','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 20:12+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'sv_SE','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Flerspråkig routing, SEO-meta-taggar och AI-innehållsverktyg för WordPress. Kombinerar språkdetection, URL-routing, hreflang, meta-beskrivningar och AI-drivna utdrag, meta och översättningsfunktioner.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Översätt','Lingua Forge — Quick Translate'=>'Lingua Forge — Snabb översättning','Informative'=>'Informativ','Persuasive'=>'Övertygande','Storytelling'=>'Berättande','Technical'=>'Teknisk','Conversational'=>'Konversativ','Permission denied.'=>'Tillstånd nekad.','Cannot determine target language from slug.'=>'Kan inte bestämma målspråk från slug.','Invalid post type.'=>'Ogiltig inläggstyp.','Invalid or primary language.'=>'Ogiltigt eller primärt språk.','Template not found or not stored in the database.'=>'Mall inte hittad eller inte lagrad i databasen.','Template has no content.'=>'Mallen har inget innehåll.','No internal links found to update.'=>'Inga interna länkar att uppdatera.','%d link updated.'=>'%d länk uppdaterad.' . "\0" . '%d länkar uppdaterade.','No language-specific template parts found to map.'=>'Inga språkspecifika malldelar att mappa.','No template part references needed updating.'=>'Inga malldelarreferenser att uppdatera.','%d part reference updated.'=>'%d delreferens uppdaterad.' . "\0" . '%d delreferenser uppdaterade.','Invalid language.'=>'Ogiltigt språk.','Template part not found or not stored in the database.'=>'Malldel inte hittad eller inte lagrad i databasen.','Template part has no content.'=>'Malldel har inget innehåll.','No navigation references needed updating.'=>'Inga navigationsreferenser att uppdatera.','%d navigation reference updated.'=>'%d navigationsreferens uppdaterad.' . "\0" . '%d navigationsreferenser uppdaterade.','No AI provider configured.'=>'Ingen AI-leverantör konfigurerad.','Missing pattern name or language.'=>'Saknas mönsternamn eller språk.','Pattern not found.'=>'Mönster inte hittat.','Pattern has no content to translate.'=>'Mönster har inget att översätta.','AI provider returned an empty response.'=>'AI-leverantören returnerade ett tomt svar.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Mönster översatt och sparat. Kopiera innehållet till ditt CPT-inlägg via blockredigerarens mönsterinsättare eller använd det som utgångspunkt för ett återanvändbart block.','Invalid template type.'=>'Ogiltig malltyp.','Template "%s" already exists.'=>'"%s" finns redan.','"%s" created.'=>'"%s" skapad.','Invalid template part.'=>'Ogiltig malldel.','Template part "%s" already exists.'=>'Malldel "%s" finns redan.','"%1$s" created. %2$d template updated.'=>'"%1$s" skapad. %2$d mallar uppdaterade.' . "\0" . '"%1$s" skapad. %2$d mallar uppdaterade.','Page'=>'Sida','Single'=>'Enkel','Search'=>'Sök','Search Results'=>'Sökresultat','Archive'=>'Arkiv','Front Page'=>'Förstasida','Single: %s'=>'Enskild: %s','Single %s'=>'Enskild %s','Archive: %s'=>'Arkiv: %s','%s Archive'=>'%s Arkiv','No source content found to translate.'=>'Hittade ingen källinnehåll att översätta.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Översatt. Granska i Webbplatsredigeraren — interna länkar, navigerings-URL:er och mall-sluggar uppdateras inte automatiskt.','Navigation not found.'=>'Navigering inte hittad.','Navigation has no content to translate.'=>'Navigering har inget innehåll att översätta.','"%1$s %2$s" saved.'=>'"%1$s %2$s" sparad.','Translate page…'=>'Översätt sida…','Generate content…'=>'Generera innehåll…','AI Behaviour Preset'=>'AI-beteendepreset','Custom'=>'Anpassad','Global default (%s)'=>'Global standard (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Överskrider AI-preset för översättning och innehållsgenerering på denna sida. Inställningar för anpassade instruktioner (Inställningar → Beteende) läggs alltid till varje förfrågan oavsett detta val.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Överskrider AI-preset för översättning och innehållsgenerering på denna sida. Alla andra funktioner använder alltid den globala presetten.','Close'=>'Stäng','Translate missing'=>'Saknar översättning','From'=>'Från','Retranslate'=>'Omarbeta','Translating…'=>'Översätter…','Retranslating…'=>'Omarbetar…','✓ Done'=>'✓ Klart','Error'=>'Fel','Navigation posts are translated via the Router tab, not this button.'=>'Navigeringsinlägg översätts via Routern-fliken, inte denna knapp.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Skapa översättningar för inläggstyp "%s" kräver en aktiv integration. Se till att den nödvändiga integrationen är installerad och aktiv.','No %s version found in this translation group.'=>'Ingen %s-version hittades i denna översättningsgrupp.','AI Usage'=>'AI-användning','Today'=>'Idag','Last 7 days'=>'Senaste 7 dagarna','Last 30 days'=>'Senaste 30 dagarna','All time'=>'Alltid','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Tokenförbrukning summerad per funktion, leverantör och modell. Registreras vid varje lyckad AI-anrop; testanslutningar utesluts avsiktligt för att inte snedvrida totalsumman. Den underliggande tabellen summerar dagligen — välj ett fönster nedan för att visa den.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Inga AI-användningar har registrerats än. När en redigerare gör en översättning, genererar en meta-beskrivning eller använder någon annan AI-funktion, visas totalsummorna här.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Inga AI-användningar registrerade i det valda fönstret (%s). Välj ett bredare intervall ovan.','Feature'=>'Funktion','Provider'=>'Leverantör','Model'=>'Modell','Requests'=>'Förfrågningar','Input tokens'=>'Inmatningstokens','Output tokens'=>'Utgångstokens','Total tokens'=>'Totalt tokens','Total'=>'Totalt','API Keys'=>'API-nycklar','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Nycklar krypteras med AES-256-CBC innan de lagras i WordPress-databasen. Krypteringshemligheten hämtas från dina WordPress-autentiseringssalter (wp-config.php), så klartextnycklar berör aldrig databasen.','API Key'=>'API-nyckel','Paste your API key…'=>'Klistra in din API-nyckel…','✓ Configured'=>'✓ Konfigurerad','✗ Not configured'=>'✗ Inte konfigurerad','Test connection'=>'Testa anslutning','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Lämna tomt för att behålla den befintliga nyckeln. Ange ett nytt värde för att ersätta den.','Remove stored key'=>'Ta bort lagrad nyckel','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Denna nyckel tillhandahålls för närvarande av en server %s och kan inte tas bort här. Ange en ny nyckel ovan för att åsidosätta den med ett databasvärde.','environment variable'=>'miljövariabel','PHP constant'=>'PHP-konstant','Alternative (server-side):'=>'Alternativ (serverside):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Du kan också definiera nycklar som konstanter eller miljövariabler (t.ex. i wp-config.php). Dessa källor används automatiskt som fallback när ingen databasnyckel är lagrad.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'För att använda en anpassad krypteringshemlighet (istället för det härledda wp_salt-värdet), lägg till detta i wp-config.php:','Unknown provider.'=>'Okänd leverantör.','No API key configured for this provider.'=>'Ingen API-nyckel konfigurerad för denna leverantör.','Could not instantiate the provider.'=>'Kunde inte instansiera leverantören.','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Leverantören returnerade inget text. Kontrollera WordPress-felloggen för den detaljerade felorsaken.','Behavior'=>'Beteende','Block Editor'=>'Blockredigerare','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge begränsar två Gutenberg-funktioner som standard för att hålla redaktionellt beteende konsekvent över språk. Välj här om du behöver fulla Gutenberg / FSE-funktioner.','Block locking'=>'Blocklåsning','Allow editors to lock individual blocks'=>'Tillåt redaktörer att låsa enskilda block','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Återaktiverar Gutenbergs canLockBlocks. Användbart för redaktionella mallar som behöver förhindra att bidragsgivare flyttar eller raderar specifika block.','Template mode'=>'Mallläge','Allow Gutenberg template-editing mode on post screens'=>'Tillåt Gutenberg-mallredigeringsläge på inläggssidor','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Återaktiverar supportsTemplateMode. Kärnan i Full-Site-Editing-arbetsflöden där mallöverskridanden på inläggsnivå är avsiktliga.','Compliance Preset'=>'Efterlevnadsförinställning','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Strikt bevarandestil för juridiskt, reglerande, medicinskt eller tekniskt innehåll. När den är aktiverad använder varje AI-funktion en låg samplingstemperatur och lägger till tillägget nedan till dess systemprompt — terminologi, artikelnummer, enheter, varumärken och reglerande språk bevaras exakt snarare än att omformuleras.','Global AI preset'=>'Global AI-förinställning','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0,2–0,6, per funktion','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Sätter den förvalda AI-beteendet för hela webbplatsen. Enskilda inlägg kan åsidosätta detta för Översättning och Innehållsgenerering via Lingua Forge-meta-rutan.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standard använder varje funktions egen justerade temperatur: Översättning T=0,2 (precis), Snabb översättning T=0,4, Innehållsgenerator T=0,6 (kreativ). De andra förinställningarna tillämpar en enda fast temperatur över alla funktioner.','Technical / Scientific instructions'=>'Tekniska / Vetenskapliga instruktioner','Legal / Compliance instructions'=>'Juridiska / Efterlevnadsinstruktioner','Creative / Marketing instructions'=>'Kreativa / Marknadsföringsinstruktioner','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Lämna tomt för att använda den inbyggda standarden. Radera en sparad överskridande inställning för att återställa standarden vid nästa spara.','View built-in default'=>'Visa inbyggd standard','Translation Memory'=>'Översättningsminne','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Cachelagra översatta motsvarigheter på blocknivå så att återanvändbart innehåll (delade sidfötter, sidospalter, akordeon, juridiska sektioner med mycket boilerplate) inte debiterar ett API-anrop varje gång. När det är aktiverat analyserar flödet varje inlägg i block, söker varje block i cachen och skickar endast okända block till AI i en enda batchförfrågan. Ändringar i ordlista och efterlevnadsförinställningar ogiltigförklarar automatiskt påverkade cachelagrade översättningar. Visa statistik och rensa cachen under Underhåll.','Enable block-level translation cache reuse across posts'=>'Aktivera blocknivå-cacheåteranvändning över inlägg','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'För närvarande hoppar den över inlägg som använder block-kommentar attributplatshållare (wp:details sammanfattningsfält, etc.) — de faller igenom till den befintliga enkel-anropsöversättningsvägen.','General'=>'Allmänt','Light'=>'Ljus','Meta Description, Excerpt Generator'=>'Meta-beskrivning, Sammanfattningsgenererare','Quality'=>'Kvalitet','Translation, Content Generator'=>'Översättning, Innehållsgenerator','Active Provider'=>'Aktiv leverantör','Currently inherited from the %s constant. Selecting a value here will override it.'=>'För närvarande ärvs från konstanten %s. Att välja ett värde här kommer att åsidosätta det.','Models'=>'Modeller','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Funktioner är grupperade i två nivåer. Ange den exakta modellidentifieraren för varje nivå och leverantör. Lämna ett fält tomt för att använda den inbyggda standarden (visas som platshållare). Endast den aktiva leverantörens modeller anropas vid körning — konfigurera de andra i förväg om du planerar att byta.','active'=>'aktiv','overridden'=>'åtsidosatt','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tips: för att återställa en modell till den inbyggda standarden, rensa fältet och spara.','Glossary'=>'Ordlista','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Användarhanterad terminologitabell per språkpar. Poster läggs till i översättningssystemets prompt så att AI:n använder föredragna termer konsekvent — avgörande för domänvokabulär ("kWp", "PPA", "interconnection point"), varumärken som inte får översättas, och standardiserad regleringsformulering. Båda språkfälten är valfria: lämna "Källspråk" tomt för att tillämpa posten oavsett vilket språk du översätter från; lämna "Mål språk" tomt för att tillämpa den på alla mål språk samtidigt.','Glossary entry added.'=>'Glossaripost tillagd.','Glossary entry removed.'=>'Glossaripost borttagen.','Could not add entry: source term and target term are required.'=>'Kunde inte lägga till post: källterm och målterm krävs.','Could not save the glossary entry.'=>'Kunde inte spara glossariposten.','Source language'=>'Källspråk','— Any —'=>'— Valfritt —','Target language'=>'Målspråk','— Any target —'=>'— Alla mål —','Filter'=>'Filtrera','Reset'=>'Återställ','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Inga glossariposter matchar det aktuella filtret. Rensa filtret för att se alla poster, eller lägg till en ny post nedan.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Inga glossariposter än. Lägg till en nedan för att börja tillämpa terminologi i översättningarna.','Source term'=>'Källterm','Target term'=>'Målterm','Source lang'=>'Källa språk','Target lang'=>'Mål språk','Notes'=>'Anteckningar','any'=>'valfritt','Delete this glossary entry?'=>'Vill du ta bort denna glossaripost?','Delete'=>'Ta bort','Add new entry'=>'Lägg till ny post','The phrase as it appears in the source text.'=>'Frasen som den förekommer i källtexten.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Hur den ska visas i översättningen. Skriv samma värde som källtermen för att instruera AI:n att behålla den exakt.','— Any source language —'=>'— Valfritt källspråk —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Lämna tomt för varumärken och språkoberoende termer som ska tillämpas oavsett vilket språk vi översätter från.','— Any target language —'=>'— Valfritt målspråk —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Lämna tomt för att tillämpa denna post på alla målspråk — idealiskt för varumärken, förkortningar och termer som måste behållas exakt i varje översättning.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Valfri kontext för redaktörer (t.ex. "ASIC = Application-Specific Integrated Circuit; behåll på engelska i tekniska sammanhang").','Add entry'=>'Lägg till post','Limits'=>'Gränser','Authors and above (edit_published_posts)'=>'Författare och högre (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Bidragsgivare och högre — standard (edit_posts)','Editors and above (edit_others_posts)'=>'Redaktörer och högre (edit_others_posts)','Administrators only (manage_options)'=>'Endast administratörer (manage_options)','AI Limits & Security'=>'AI-gränser & säkerhet','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Begränsa hur mycket AI-användning webbplatsen kan generera och begränsa vilka användarroller som kan utlösa betalda AI-anrop. Sitter ovanpå den per-användare takgräns (30 förfrågningar / minut, hårdkodat) som redan skyddar mot enskilda användare som springer iväg.','Daily request limit'=>'Dagligt förfrågningsgräns','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Webbplatsövergripande tak för AI-förfrågningar per UTC-dag (räknar både Verktygsfältets översättningar och blockrevisioner). Räknaren återställs vid UTC-midnatt. Sätt till 0 för att inaktivera taket.','Minimum role'=>'Minsta roll','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Lägsta WordPress-kompetens som tillåts utlösa AI-funktioner. Att begränsa detta på flerskaparesajter förhindrar Bidragsgivare eller testkonton från att köra betalda AI-anrop. Överstyr per funktion via filteret linguaforge_required_capability.','Translation Limits'=>'Översättningsgränser','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Kontrollera hur mycket innehåll som skickas till AI och hur stort svaret kan vara. Lämna ett fält tomt för att använda den inbyggda standarden (visas som platshållare). Höj dessa värden om stora sidor klipps av; sänk dem för att minska API-kostnader.','Model tier'=>'Modellnivå','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Kvalitet (standard — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Ljus (snabbt och kostnadseffektivt — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Vilken modellnivå som ska användas för helsidetranslation. Kvalitet använder modellen konfigurerad i tabellen Modeller ovan och rekommenderas för noggrann, långformig översättning. Byt till Ljus endast om hastighet eller kostnad är prioriterat och innehållet är kort.','Max output tokens'=>'Max utdata tokens','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Maximalt antal tokens som AI kan producera i ett enda översättningssvar. Om en översättning tyst klipps av i slutet, öka detta värde. Standard: 16 000.','Max input characters'=>'Max inmatningskaraktärer','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Maximalt antal tecken för inläggets innehåll som vidarebefordras till AI. 0 betyder ingen gräns — hela innehållet skickas alltid (rekommenderas). Sätt ett icke-nollvärde endast om din leverantör har ett snävt sammanhangsfönster. En varning skrivs till PHP-felloggen när innehållet klipps.','Quick Translation'=>'Snabb översättning','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Snabb översättning används för snipp- eller chunk-läge — korta passager översätts på begäran från verktygsfältet, redigeraren eller blockets popovers. Det använder en separat, lättare konfiguration än helsidetranslation för att hålla svaren snabba och kostnadseffektiva.','Light (default — fast and cost-effective)'=>'Lätt (standard — snabbt och kostnadseffektivt)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Kvalitet (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Lättnivån använder den snabba modellen som konfigurerats i tabellen Modeller ovan (standard: Haiku / Flash). Byt till Kvalitet om du behöver samma översättningsnoggrannhet som i helsidläge för snippar.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Maximalt antal tokens som AI kan producera per snabb översättning. Standard: 2 000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Maximalt antal tecken som accepteras från inmatningsfältet. Standard: 8 000.','Content Generator'=>'Innehållsgenerator','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Styr tokenbudget och inmatningsgränser för AI Content Generator-funktionen. Lämna fälten tomma för att använda de inbyggda standardvärdena.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Maximalt antal tokens som AI kan producera per genereringskörning. Öka detta om hela artiklar klipps av. Standard: 8 192.','Max hints characters'=>'Max antal hints-tecken','Maximum characters read from the Hints field. Default: 2 000.'=>'Maximalt antal tecken som läses från hints-fältet. Standard: 2 000.','Max context characters'=>'Maximalt sammanhangstecken','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Maximalt antal tecken av befintligt inläggs innehåll som skickas till AI som frö-sammanhang när inga hints ges. Standard: 6 000.','Maintenance'=>'Underhåll','Language Overrides'=>'Språköverskridanden','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Ladda upp kompilerade .mo-filer för att åsidosätta strängar från tredjepartsplugin för specifika språk — till exempel en anpassad VikBooking-översättning som använder "lägenhet" istället för "rum". Filer måste följa WordPress-namnkonventionen: {textdomain}-{locale}.mo (t.ex. vikbooking-ca.mo). De lagras i uppladdningsmappen och överlever plugin-uppdateringar.','Override file uploaded successfully.'=>'Åsidosättningsfil uppladdad framgångsrikt.','Override file deleted.'=>'Åsidosättningsfil raderad.','No file was selected.'=>'Ingen fil valdes.','Only .mo files are accepted.'=>'Endast .mo-filer accepteras.','The upload failed — please try again.'=>'Uppladdningen misslyckades — försök igen.','Could not save the file. Check that the uploads folder is writable.'=>'Kunde inte spara filen. Kontrollera att uppladdningsmappen är skrivbar.','Invalid filename.'=>'Ogiltigt filnamn.','Security check failed — file path is not permitted.'=>'Säkerhetskontroll misslyckades — filvägen är inte tillåten.','An unknown error occurred.'=>'Ett okänt fel inträffade.','Text domain / locale'=>'Textdomän / språk','Files'=>'Filer','Size'=>'Storlek','Delete all files for this override (both .mo and .po)?'=>'Ta bort alla filer för denna åsidosättning (både .mo och .po)?','No override files uploaded yet.'=>'Inga åsidosättningsfiler har laddats upp än.','Upload .mo file'=>'Ladda upp .mo-fil','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Accepterar endast kompilerade .mo-filer. Filnamnet måste följa mönstret {textdomain}-{locale}.mo. Att ladda upp en fil med samma namn som en befintlig kommer att ersätta den.','Upload Override'=>'Ladda upp åsidosättning','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Kopiera till säkert lagringsutrymme','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate lagrar sina anpassade översättningar i wp-content/languages/loco/ — en plats som kan raderas tyst av en WP-kärnuppdatering, plugin-ominstallation eller om Loco Translate tas bort. Att kopiera filer hit flyttar dem till Lingua Forge i18n-overrides-katalogen, som består genom alla dessa händelser och laddas automatiskt vid varje förfrågan.','File copied to safe storage successfully.'=>'Fil kopierad till säkert lagringsutrymme framgångsrikt.','Source file not found.'=>'Källfilen hittades inte.','Could not copy the file. Check that the uploads folder is writable.'=>'Kunde inte kopiera filen. Kontrollera att uppladdningsmappen är skrivbar.','Invalid file reference.'=>'Ogiltig filreferens.','Type'=>'Typ','✓ In safe storage'=>'✓ I säkert lagringsutrymme','Copy to safe storage'=>'Kopiera till säkert lagringsutrymme','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Inga anpassade Loco Translate-filer har hittats än. De visas här när du sparar en översättning i Loco Translate.','AI Cache'=>'AI-cache','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'Lingua Forge cachar AI-genererade översättningar, meta-beskrivningar, utdrag och genererat innehåll per inlägg så att oförändrade inmatningar inte utlöser ett betalt API-anrop. Cache-inlägg ogiltigförklaras automatiskt när deras inmatningar ändras. Rensa cachen manuellt för att återta databasutrymme, tvinga en synkronisering efter att ha bytt leverantör eller redigerat promptmallar, eller felsöka ett cache-relaterat problem.','AI cache cleared. %d entry was removed.'=>'AI-cache rensad. %d post togs bort.' . "\0" . 'AI-cache rensad. %d poster togs bort.','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Rensa alla cachade AI-resultat? Framtida förfrågningar kommer att utlösa nya API-anrop tills cachen byggs om.','Clear AI Cache'=>'Rensa AI-cache','Debug Files'=>'Felsökningsfiler','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'När felsökningsloggning är aktiverad (via växeln nedan eller genom att definiera LINGUAFORGE_AI_DEBUG i wp-config.php) skriver översättnings- och FSE-mallöversättningsfunktionerna sina råa AI-uppmaningar och svar till disk för felsökning. Använd detta avsnitt för att övervaka den utskriften och rensa den när du har det du behöver — filerna kan växa snabbt på stora sidor. Konfigurera målmappen via filtreringen linguaforge_debug_dir.','Debug files cleared. %d file was removed.'=>'Felsökningsfiler rensade. %d fil togs bort.' . "\0" . 'Felsökningsfiler rensade. %d filer togs bort.','Debug logging enabled.'=>'Felsökningsloggning aktiverad.','Debug logging disabled.'=>'Felsökningsloggning inaktiverad.','Debug logging'=>'Felsökningsloggning','Write AI prompts and responses to disk for troubleshooting'=>'Skriv AI-uppmaningar och svar till disk för felsökning','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Tvingad PÅ av konstanten LINGUAFORGE_AI_DEBUG i wp-config.php. Ta bort den raden för att kontrollera växeln härifrån.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Tvingad AV av konstanten LINGUAFORGE_AI_DEBUG i wp-config.php. Ta bort den raden för att kontrollera växeln härifrån.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Filer hamnar i nedanstående katalog. Användbart för att diagnostisera översättningsproblem — stäng av när du har det du behöver så att filerna inte samlas. Du kan också tvinga detta från wp-config.php med `define( \'LINGUAFORGE_AI_DEBUG\', true );` vilket överskrider växeln.','Currently:'=>'För närvarande:','✓ Enabled'=>'✓ Aktiverad','✗ Disabled'=>'✗ Inaktiverad','Directory'=>'Katalog','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtrera med linguaforge_debug_dir för att omdirigera felsökningsutdata till en icke-offentlig plats.','.txt file(s) in the directory'=>'.txt-fil(er) i katalogen','Save Debug Setting'=>'Spara felsökningsinställning','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Radera alla .txt-filer i felsökningskatalogen? Katalogen själv kommer att förbli så att framtida felsökningsskrivningar fortfarande hamnar rätt.','Clear Debug Files'=>'Rensa felsökningsfiler','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'Per-block översättningscache som delas mellan inlägg. Konfigurera på/av i Inställningar → Beteende. Statistik nedan visar vad som för närvarande cachas; att rensa tvingar varje block att översättas om på nästa förfrågan (användbart efter uppgradering av modeller eller för att återställa databasutrymme).','Translation Memory cleared. %d cached block was removed.'=>'Översättningstextminne rensat. %d cachade block togs bort.' . "\0" . 'Översättningstextminne rensat. %d cachade block togs bort.','Status'=>'Status','— toggle in Settings → Behavior.'=>'— växla i Inställningar → Beteende.','Cached blocks'=>'Cachade block','Cumulative cache hits'=>'Kumulativa cacheträffar','(avg %.1f hits/block)'=>'(genomsnitt %.1f träffar/block)','Oldest entry'=>'Äldsta post','Newest entry'=>'Nyaste post','Approximate size'=>'Ungefärlig storlek','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Rensa hela översättningstextminnet? Framtida översättningar kommer att bygga om cachen när de körs.','Clear Translation Memory'=>'Rensa översättningstextminne','Uninstall Behaviour'=>'Avinstallera Beteende','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Styr vad som händer när en administratör tar bort pluginet från Plugins → Installerade Plugins → Ta bort. Plugin-inställningar och AI-cache raderas alltid. Språkuppdrag och översättningsrelationer behålls som standard så att en oavsiktlig avinstallation eller ominstallation kan fortsätta där den slutade.','Uninstall setting saved.'=>'Avinstallationsinställning sparad.','Delete content data on uninstall'=>'Radera innehållsdata vid avinstallation','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Radera också språkuppdrag, översättningsrelationer, metabeskrivningar, ordlista och översättningstextminne när pluginet avinstalleras','Warning:'=>'Varning:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Om markerad kommer avinstallationen av pluginet att permanent radera alla språkuppdrag, översättningsrelationer, metabeskrivningar, sidbaserade förinställningar, AI-ordlistan och översättningstextminnet för varje inlägg på denna webbplats. Detta kan inte ångras. Lämna omarkerat om du helt tar bort flerspråkstöd från webbplatsen.','Save Uninstall Setting'=>'Spara avinstallationsinställning','Router'=>'Router','Primary language saved.'=>'Primärt språk sparat.','Permalink rules flushed successfully.'=>'Permalänkrensning lyckades.','Primary Language'=>'Primärt språk','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Det primära språket tjänas alltid på rotad av din webbplats — ingen URL-prefix i sökvägsmode, ingen språksubdomän i subdomänläge. Alla andra språk använder antingen en /lang/ sökvägsprefix (t.ex. example.com/de/) eller en språksubdomän (t.ex. de.example.com), beroende på URL-strukturinställningen nedan.','Primary language'=>'Primärt språk','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Efter att ha ändrat det primära språket, töm permalänkar (avsnitt nedan) för att uppdatera URL-routing.','URL structure'=>'URL-struktur','Path prefix — example.com/de/'=>'Sökvägsprefix — example.com/se/','Subdomain — de.example.com/'=>'Subdomän — de.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Subdomänläge kräver att din webbserver pekar alla språksubdomäner (t.ex. de.example.com) till denna WordPress-installation. Efter att ha bytt läge, töm permalänregler och rensa eventuella cache. Om din hemsides-URL inkluderar www (t.ex. www.example.com), använd lf_base_domain-filtret för att ställa in den rena toppdomänen så att subdomäner konstrueras korrekt.','Browser language redirect'=>'Webbläsarspråk-omdirigering','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Omdirigera besökare till deras föredragna språk baserat på webbläsarens Accept-Language-header','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'När detta är aktiverat omdirigeras förstagångsbesökare utan språkcookie och utan språkprefix i URL:en till den närmaste matchande språkversionen. Omdirigeringen hoppas över om webbläsarens föredragna språk inte är bland de aktiva router-språken. När en besökare väljer ett språk via switchern, prioriteras cookien och webbläsarens header ignoreras vid framtida besök.','Save Router Settings'=>'Spara routerinställningar','Flush Permalinks'=>'Töm permalänkar','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regenererar WordPress-omskrivningsregler så URL-prefix, språkspecifika slugs och arkivomskrivningar är i synk. Nödvändigt efter att ha ändrat primärt språk eller lagt till nytt språkstöd.','Flush Permalink Rules'=>'Töm permalänkriktlinjer','Active Languages'=>'Aktiva språk','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Språk som för närvarande är kända för routern (hämtade från installerade WordPress-lokalpaket plus det primära språket). Installera ytterligare språkpaket i avsnittet nedan för att göra fler språk tillgängliga för routing och översättning.','%d locale pack installed.'=>'%d lokalpaket installerat.' . "\0" . '%d lokalpaket installerade.','Install a Language'=>'Installera ett språk','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Ladda ner och installera ett WordPress-kärnspråkpaket direkt från WordPress.org. När det är installerat blir språket tillgängligt för URL-routing och AI-översättningsarbetsflödet. Listan över tillgängliga språk hämtas vid behov — klicka på knappen nedan för att ladda den.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Språkinstallation är inaktiverad på denna server. Konstanten DISALLOW_FILE_MODS är inställd i wp-config.php. Installera språkpaket manuellt via WP-CLI: wp language core install de_DE','Load available languages'=>'Ladda tillgängliga språk','— select a language —'=>'— välj ett språk —','Install'=>'Installera','Language Setup'=>'Språksetup','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Inga sekundära språk konfigurerade. Installera ett språkpaket ovan för att aktivera mallstrukturering.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Välj ett språk för att hantera dess FSE-mallar, malldelar och navigationsmenyer.','Forbidden'=>'Förbjuden','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Språkinstallation är inaktiverad på denna server (DISALLOW_FILE_MODS är inställt).','Invalid locale code.'=>'Ogiltig lokal kod.','Language %s installed successfully.'=>'Språket %s installerades framgångsrikt.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Installation av språkpaket misslyckades. Språket kan redan vara installerat, lokal-koden kan vara felaktig, eller så kan din server blockera filskrivningar.','Navigations'=>'Navigationer','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Navigation översättning kräver en aktiv AI-leverantör. Konfigurera en API-nyckel i fliken API-nycklar.','Navigation'=>'Navigation','Action'=>'Åtgärd','Re-translate'=>'Oversätt igen','CPT Block Patterns'=>'CPT Blockmönster','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Blockmönster registrerade för anpassade inläggstyper. Använd knappen Översätt för att skapa en språkvariant. Det översatta innehållet sparas här och kan kopieras till vilket CPT-inlägg som helst från blockredigerarens mönsterinserter eller användas som utgångspunkt för ett Synkroniserat mönster (Återanvänt block).','Pattern'=>'Mönster','Post Types'=>'Inläggstyper','✓ Translation saved'=>'✓ Översättning sparad','View'=>'Visa','Template Parts'=>'Malldelar','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Språk-specifika kopior av temats malldelar. När de är scaffoldade, uppdateras mallarna för att referera till den språk-specifika delen.','Part'=>'Del','Status / Actions'=>'Status / Åtgärder','Fix Links'=>'Fixa länkar','Fix Nav'=>'Fixa navigation','Create'=>'Skapa','Templates'=>'Mallar','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'FSE-mallar sådda från det aktiva temat. Skapa och anpassa i webbplatsredigeraren.','Actions'=>'Åtgärder','Fix Parts'=>'Fixa delar','Create missing'=>'Skapa saknade','Translate all'=>'Översätt allt','Fix all parts'=>'Fixa alla delar','Fix all links'=>'Fixa alla länkar','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','Testing…'=>'Testar…','✓ Connection OK'=>'✓ Anslutning OK','✗ Failed:'=>'✗ Misslyckades:','No response from provider — check the error log for details.'=>'Ingen respons från leverantören — kontrollera felloggen för detaljer.','Network error — could not reach the WordPress AJAX endpoint.'=>'Nätverksfel — kunde inte nå WordPress AJAX-endpointen.','Loading…'=>'Läser in…','Installing…'=>'Installerar…','✓ Language installed.'=>'✓ Språk installerat.','✗ Error:'=>'✗ Fel:','Creating…'=>'Skapar…','✓ All templates created.'=>'✓ Alla mallar skapade.','Some templates could not be created.'=>'Vissa mallar kunde inte skapas.','✓ All parts created.'=>'✓ Alla delar skapade.','Some parts could not be created.'=>'Vissa delar kunde inte skapas.','✓ All translated.'=>'✓ Alla översatta.','Some translations failed.'=>'Vissa översättningar misslyckades.','Review carefully — links and slugs not updated.'=>'Granska noggrant — länkar och slugs är inte uppdaterade.','Fixing…'=>'Fixar…','✓ Links fixed.'=>'✓ Länkar fixade.','Some link fixes failed.'=>'Vissa länkfix misslyckades.','✓ Parts fixed.'=>'✓ Delar fixade.','Some part fixes failed.'=>'Vissa delfix misslyckades.','✓ Nav refs fixed.'=>'✓ Navigationsreferenser fixade.','Some nav ref fixes failed.'=>'Vissa navigationsreferensfix misslyckades.','✓ Pattern translated.'=>'✓ Mönster översatt.','Pattern translation failed.'=>'Mönsteröversättning misslyckades.','Hide'=>'Dölj','Built-in preset instructions:'=>'Inbyggda förinställda instruktioner:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Inga inbyggda instruktioner — varje AI-funktion använder sina egna justerade standardinställningar. Fyll i fältet för anpassade instruktioner nedan för att lägga till dina egna regler för hela webbplatsen.','Settings'=>'Inställningar','You do not have permission to manage these settings.'=>'Du har inte behörighet att hantera dessa inställningar.','Lingua Forge — Settings'=>'Lingua Forge — Inställningar','Settings saved.'=>'Inställningar sparade.','Save Settings'=>'Spara inställningar','Standard'=>'Standard','Technical / Scientific'=>'Tekniskt / Vetenskapligt','Legal / Compliance'=>'Juridiskt / Efterlevnad','Creative / Marketing'=>'Kreativt / Marknadsföring','Full Article'=>'Full artikel','Introduction only'=>'Endast introduktion','Structured Outline'=>'Strukturerad disposition','Generate Content'=>'Generera innehåll','Hints'=>'Tips','Key points, ideas, or structure to build from…'=>'Huvudpunkter, idéer eller struktur att bygga från…',